      const bodies = ['meridian', 'harbor'].flatMap(tenant => [message(tenant, 'v-erased', T0 - 1), message(tenant, 'v-erased', T0, true),
        message(tenant, 'v-erased', T0 + 1), message(tenant, 'v-other', T0 - 1, true)]);
